<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/arn_features.php';
arn_require_role(['manager']);
$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');
$sql="SELECT a.id,a.asset_id,a.asset_type,a.asset_brand,a.asset_details,a.created_at,u.name AS customer_name,u.email AS customer_email,COUNT(DISTINCT sr.id) AS service_count FROM assets a LEFT JOIN users u ON u.email COLLATE utf8mb4_unicode_ci = a.customer_email COLLATE utf8mb4_unicode_ci LEFT JOIN service_requests sr ON sr.asset_ref_id=a.id WHERE 1=1";$params=[];if($q!==''){$sql.=' AND (a.asset_id LIKE ? OR a.customer_email LIKE ? OR u.name LIKE ?)';$like="%$q%";array_push($params,$like,$like,$like);}if($type!==''){$sql.=' AND a.asset_type=?';$params[]=$type;}$sql.=' GROUP BY a.id ORDER BY a.id DESC';$st=$pdo->prepare($sql);$st->execute($params);$assets=$st->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Asset Management | ARN QuickFix</title><link href="css/bootstrap.min.css" rel="stylesheet"></head><body style="background:#F8FAFC"><div class="container-fluid px-4 py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold mb-1">Asset Management</h2><p class="text-secondary mb-0">Canonical customer asset registry and service history.</p></div><a href="manager-dashboard.php" class="btn btn-outline-secondary rounded-pill">Back</a></div><form class="row g-2 mb-4"><div class="col-md-6"><input name="q" value="<?=htmlspecialchars($q)?>" class="form-control" placeholder="Search Asset ID, customer or email"></div><div class="col-md-3"><select name="type" class="form-select"><option value="">All types</option><option value="AC" <?=$type==='AC'?'selected':''?>>AC</option><option value="Elevator" <?=$type==='Elevator'?'selected':''?>>Elevator</option><option value="Generator" <?=$type==='Generator'?'selected':''?>>Generator</option></select></div><div class="col-md-2"><button class="btn btn-dark w-100">Search</button></div></form><div class="bg-white border rounded-4 p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Asset ID</th><th>Type</th><th>Brand / Details</th><th>Customer</th><th>Service History</th><th>Registered</th></tr></thead><tbody><?php foreach($assets as $a):?><tr><td class="font-monospace fw-bold text-primary"><?=htmlspecialchars($a['asset_id'])?></td><td><?=htmlspecialchars($a['asset_type'])?></td><td><strong><?=htmlspecialchars($a['asset_brand']??'—')?></strong><div class="small text-secondary"><?=htmlspecialchars($a['asset_details']??'')?></div></td><td><?=htmlspecialchars($a['customer_name']??'—')?><div class="small text-secondary"><?=htmlspecialchars($a['customer_email'])?></div></td><td><?= (int)$a['service_count'] ?> request(s)</td><td><?=htmlspecialchars(date('d M Y',strtotime($a['created_at'])))?></td></tr><?php endforeach;?><?php if(!$assets):?><tr><td colspan="6" class="text-center text-secondary py-5">No assets found.</td></tr><?php endif;?></tbody></table></div></div></div></body></html>
